describe('Date Picker Keyboard Accessibility', () => {
    beforeEach(() => {
        cy.visit('/date-picker'); // Adjust the URL to your application's date picker page
    });

    it('should open the date picker when the input is focused and Enter is pressed', () => {
        cy.get('input[type="text"]').focus().type('{enter}');
        cy.get('.datepicker').should('be.visible');
    });

    it('should navigate through dates using arrow keys', () => {
        cy.get('input[type="text"]').focus().type('{enter}');
        cy.get('.datepicker').should('be.visible');

        cy.get('.datepicker').find('.day').first().should('have.class', 'selected');

        cy.get('input[type="text"]').type('{rightarrow}');
        cy.get('.datepicker').find('.day').eq(1).should('have.class', 'selected');

        cy.get('input[type="text"]').type('{leftarrow}');
        cy.get('.datepicker').find('.day').first().should('have.class', 'selected');
    });
});
